import java.io.ByteArrayOutputStream
import java.io.StringWriter

class AvoidInMemoryStreamingDefaultConstructor {
    fun bad() {
        var baos = ByteArrayOutputStream() //bad
        val sw = StringWriter() //bad
    }
    fun good() {
        val baos = ByteArrayOutputStream(8192) // 8 kiB
        val sw = StringWriter(2048)
    }
}

import java.io.ByteArrayOutputStream
import java.io.StringWriter

class AvoidInMemoryStreamingDefaultConstructor {
    fun bad() {
        val baos = ByteArrayOutputStream(32) //bad - not larger than default
        val sw = StringWriter(16) //bad - not larger than default
    }
    fun good() {
        val baos = ByteArrayOutputStream(8192) // 8 kiB
        val sw = StringWriter(2048)
        val sw2 = StringWriter(17)
    }
}

import java.io.ByteArrayOutputStream
import java.io.StringWriter

class Issue616 {

    fun withPiWriter(onlyForMuzzlPMD: Int, proc: Consumer<PiWriter>): String {
        StringWriter(onlyForMuzzlPMD).use { stringWriter ->
            PiWriter(stringWriter).use { piWriter ->
                proc.accept(piWriter)
                piWriter.flush()
                return stringWriter.toString()
            }
        }
    }
    fun toGzip(decompressed: ByteArray) =
        runCatching {
            ByteArrayOutputStream(decompressed.size).use { baos ->
                GZIPOutputStream(baos).use { gzos ->
                    gzos.write(decompressed)
                    gzos.finish()
                    baos.toByteArray()
                }
            }
        }

     fun readBodyBytes(dbf: List<DataBuffer>): ByteArray {
        return ByteArrayOutputStream(BUFFER_SIZE_BYTES).use { boas ->
            dbf.forEach { db ->
                val b = db.asInputStream().readBytes()
                boas.writeBytes(b)
            }
            boas.toByteArray()
        }
     }
}
